package com.guillermomolina.protos.cli;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import org.junit.jupiter.api.Test;final class ProtosCliTest{private R run(String...a){var o=new ByteArrayOutputStream();var e=new ByteArrayOutputStream();int c=new ProtosCli().run(a,InputStream.nullInputStream(),new PrintStream(o),new PrintStream(e));return new R(c,o.toString(StandardCharsets.UTF_8),e.toString(StandardCharsets.UTF_8));}@Test void helpVersionEvalStringNull(){assertEquals(0,run("--help").c);assertTrue(run("--version").o.startsWith("Protos "));assertEquals("2\n",run("-e","1 + 1").o);assertEquals("\"hello\"\n",run("-e","\"hello\"").o);assertEquals("null\n",run("-e","null").o);}@Test void syntaxUsageFileArgs()throws Exception{assertNotEquals(0,run("-e","(").c);assertEquals(2,run("-e").c);Path f=Files.createTempFile("protos-cli-",".protos");try{Files.writeString(f,"1 + 1");assertEquals("2\n",run(f.toString()).o);assertEquals(2,run(f.toString(),"one").c);}finally{Files.deleteIfExists(f);}assertNotEquals(0,run(f.toString()).c);}private record R(int c,String o,String e){}}
